<?php
namespace App\Application\Orders\Services;
use App\Application\Coupons\Services\CouponService;use App\Domain\Contracts\Repositories\OrderRepositoryInterface;use App\Domain\Contracts\TransactionManagerInterface;use App\Domain\Models\Order;use Illuminate\Support\Str;use InvalidArgumentException;
class OrderService{public function __construct(private readonly CouponService $coupons,private readonly OrderRepositoryInterface $repository,private readonly TransactionManagerInterface $transactions){}public function createForUser(int|string $userId,array $data):Order{return $this->transactions->run(function()use($userId,$data){$cart=$this->repository->cartForCheckout((string)$userId);if(!$cart||$cart->items->isEmpty())throw new InvalidArgumentException('لا يمكن إنشاء طلب بسلة فارغة.');$subtotal=0;foreach($cart->items as $item){$stock=$item->variant?->stock_quantity??$item->product->stock;if($item->quantity>$stock)throw new InvalidArgumentException("المخزون غير كافٍ للمنتج: {$item->product->name}");$price=(float)($item->variant?->price??$item->product->price);$subtotal+=$price*$item->quantity;}$coupon=!empty($data['coupon_code'])?$this->coupons->findValid($data['coupon_code'],$userId,$subtotal):null;$discount=$coupon?$this->coupons->discount($coupon,$subtotal):0;$shipping=(float)($data['shipping_cost']??0);$order=$this->repository->create(['order_number'=>'ORD-'.now()->format('YmdHis').'-'.strtoupper(Str::random(5)),'user_id'=>$userId,'subtotal'=>$subtotal,'discount_amount'=>$discount,'shipping_cost'=>$shipping,'grand_total'=>max(0,$subtotal-$discount+$shipping),'payment_method'=>$data['payment_method']??'cod','shipping_full_name'=>$data['shipping_full_name'],'shipping_phone'=>$data['shipping_phone'],'shipping_city'=>$data['shipping_city'],'shipping_address'=>$data['shipping_address'],'notes'=>$data['notes']??null]);foreach($cart->items as $item){$price=(float)($item->variant?->price??$item->product->price);$attrs=$item->variant?->attributes??[];$this->repository->addItem($order,['product_id'=>$item->product_id,'product_variant_id'=>$item->product_variant_id,'product_name'=>$item->product->name,'variant_name'=>$attrs?json_encode($attrs,JSON_UNESCAPED_UNICODE):null,'unit_price'=>$price,'quantity'=>$item->quantity,'total_price'=>$price*$item->quantity]);$this->repository->decrementStock($item);}if($coupon){$this->repository->incrementCoupon($coupon);$this->repository->recordCoupon($coupon,(string)$userId,$order->id,$discount);}$this->repository->clearCart($cart);return $order->load('items');});}public function listForUser(int|string $id){return $this->repository->listForUser((string)$id);}public function listAll(){return $this->repository->listAll();}public function getForUser(int|string $id,string $orderId):Order{return $this->repository->findForUser((string)$id,$orderId);}public function cancel(Order $order):Order{return $this->transactions->run(function()use($order){$order=$this->repository->lock($order->id);if(!in_array($order->status,['pending','processing'],true))throw new InvalidArgumentException('لا يمكن إلغاء الطلب بعد شحنه أو تسليمه.');foreach($order->items as $item)$this->repository->incrementStock($item->product_id,$item->product_variant_id,$item->quantity);if($order->payment_status!=='pending')throw new InvalidArgumentException('لا يمكن إلغاء طلب مدفوع قبل تنفيذ عملية الاسترداد.');$order->update(['status'=>'cancelled']);return $order->fresh('items');});}public function updateStatus(string $id,string $status):Order{return $this->transactions->run(function()use($id,$status){$order=$this->repository->lock($id);$allowed=['pending'=>['processing','cancelled'],'processing'=>['shipped','cancelled'],'shipped'=>['delivered'],'delivered'=>[],'cancelled'=>[]];if(!in_array($status,$allowed[$order->status]??[],true))throw new InvalidArgumentException('انتقال حالة الطلب غير مسموح.');if($status==='cancelled')return $this->cancel($order);$order->update(['status'=>$status]);return $order->fresh('items');});}}
